[ERRORS] errors[] empty {DOC}
[DATA] data.customerSalesReps.totalCount >= 1 {DOC}
[DATA] every items[].fullName contains the keyword substring (case-insensitive) {DOC}

[ERRORS] (asc) errors[] empty {DOC}
[ERRORS] (desc) errors[] empty {DOC}
