Assertions:
[ERRORS] errors[] empty {DOC}
[DATA] data.salesRepCustomer.organizationId = {{org}} {DOC}
[DATA] data.salesRepCustomer.organizationName is non-empty {DOC}
[DATA] data.salesRepCustomer.primaryContact is non-null {DOC}

[ERRORS] errors[] empty {DOC}
[DATA] data.salesRepCustomer.primaryContact.id is non-empty GUID {DOC}
[DATA] data.salesRepCustomer.primaryContact.id does NOT equal SR_REP_PRIMARY's own contact id (the explicit org Owner wins over the rep's own membership) {DOC}
[DATA] data.salesRepCustomer.phone is non-empty (falls back to the primary contact's phone) {DOC}

[ERRORS] errors[] empty {DOC}
[DATA] data.salesRepCustomer.accountType is non-empty (mirrors org BusinessCategory) {DOC}
